"""Place the real product cutouts on the themed backdrops generated by Codex.

Usage: python3 scripts/compose-corps.py
Reads assets-src/corps/detours/NN.png and assets-src/corps/decors/*.png,
writes src/assets/products/corps-NN.jpg (1080x1350, the 4:5 card ratio).
The product pixels are never redrawn, only scaled, lightly tinted and shadowed,
so labels stay exactly as on the real packaging.
"""
from pathlib import Path

from PIL import Image, ImageChops, ImageDraw, ImageFilter, ImageOps

ROOT = Path(__file__).resolve().parent.parent
CUTS = ROOT / 'assets-src/corps/detours'
DECORS = ROOT / 'assets-src/corps/decors'
OUT = ROOT / 'src/assets/products'
W, H = 1080, 1350

# Backdrop name -> height of the plinth top, as a fraction of the image height.
PLINTH = {
    'decor-chaouen': 0.65,
    'decor-zellige': 0.642,
    'decor-hammam': 0.65,
    'decor-aube': 0.66,
    'decor-nuit': 0.665,
}

# Cutout number -> backdrop. Chosen for contrast between packaging and scene.
SCENES = {
    '01': 'decor-nuit', '02': 'decor-chaouen', '04': 'decor-aube', '05': 'decor-chaouen',
    '07': 'decor-zellige', '08': 'decor-chaouen', '09': 'decor-zellige', '10': 'decor-aube',
    '12': 'decor-nuit', '13': 'decor-chaouen', '14': 'decor-zellige', '15': 'decor-nuit',
    '16': 'decor-aube', '17': 'decor-zellige', '18': 'decor-nuit', '19': 'decor-hammam',
    '20': 'decor-chaouen', '21': 'decor-hammam', '22': 'decor-zellige',
}

# Cutouts with a swing tag under the bottle need a stricter trim.
TRIM = {'19': 0.75}


def cover(img: Image.Image) -> Image.Image:
    return ImageOps.fit(img.convert('RGB'), (W, H), Image.LANCZOS, centering=(0.5, 0.5))


def tint_towards(product: Image.Image, scene: Image.Image, amount: float = 0.05) -> Image.Image:
    """Nudge the product colours towards the scene's ambient light so it sits in the room."""
    ambient = scene.resize((1, 1), Image.BOX).getpixel((0, 0))
    rgb = product.convert('RGB')
    tinted = Image.blend(rgb, Image.new('RGB', rgb.size, ambient), amount)
    tinted.putalpha(product.getchannel('A'))
    return tinted


def erode(cut: Image.Image) -> Image.Image:
    """Shave the cutout edge by a few pixels to drop the light fringe left from the table and wall."""
    cut.putalpha(cut.getchannel('A').filter(ImageFilter.MinFilter(7)))
    return cut


def trim_bottom(cut: Image.Image, ratio: float = 0.4) -> Image.Image:
    """Drop thin bits hanging under the base (a swing tag, a stray strap) so the product stands on its base."""
    alpha = cut.getchannel('A').point(lambda a: 255 if a > 128 else 0)
    widths = [sum(1 for v in alpha.crop((0, y, cut.width, y + 1)).get_flattened_data() if v) for y in range(cut.height)]
    widest = max(widths)
    bottom = cut.height
    while bottom > cut.height // 2 and widths[bottom - 1] < widest * ratio:
        bottom -= 1
    return cut.crop((0, 0, cut.width, bottom))


def lift(cut: Image.Image) -> Image.Image:
    """Phone photos are dim next to the studio scenes: brighten the product by a single gain.

    A plain multiply keeps every hue exactly as on the packaging (contrast stretches shift colours).
    """
    alpha = cut.getchannel('A')
    gray = cut.convert('L')
    mask = alpha.point(lambda a: 255 if a > 128 else 0)
    hist = gray.histogram(mask)
    total = sum(hist)
    mean = sum(i * n for i, n in enumerate(hist)) / total
    gain = max(1.0, min(1.3, 150 / mean))
    rgb = cut.convert('RGB').point(lambda v: min(255, round(v * gain)))
    rgb.putalpha(alpha)
    return rgb


def compose(num: str, decor: str) -> Image.Image:
    scene = cover(Image.open(DECORS / f'{decor}.png'))
    cut = lift(trim_bottom(erode(Image.open(CUTS / f'{num}.png').convert('RGBA')), TRIM.get(num, 0.4)))

    # Bottles stand tall, boxes lie wide: fit inside a box that suits both.
    max_h, max_w = H * 0.56, W * 0.52
    scale = min(max_h / cut.height, max_w / cut.width)
    cut = cut.resize((round(cut.width * scale), round(cut.height * scale)), Image.LANCZOS)
    alpha = cut.getchannel('A').filter(ImageFilter.GaussianBlur(0.8))
    cut.putalpha(alpha)
    cut = tint_towards(cut, scene)

    base_y = round(H * (PLINTH[decor] + 0.017))
    x = (W - cut.width) // 2
    y = base_y - cut.height + round(cut.height * 0.012)

    # Contact shadow: a tight dark line under the base, a wider soft pool, and a faint cast shadow.
    def ellipse(width: float, height: float, blur: float) -> Image.Image:
        layer = Image.new('L', (W, H), 0)
        ImageDraw.Draw(layer).ellipse([W / 2 - width / 2, base_y - height / 2, W / 2 + width / 2, base_y + height / 2], fill=255)
        return layer.filter(ImageFilter.GaussianBlur(blur))

    tight = ellipse(cut.width * 1.04, 18, 6).point(lambda a: a * 0.75)
    pool = ellipse(cut.width * 1.6, 70, 26).point(lambda a: a * 0.5)
    cast = Image.new('L', (W, H), 0)
    cast.paste(cut.getchannel('A').point(lambda a: a * 0.22), (x + 22, y + 8))
    cast = cast.filter(ImageFilter.GaussianBlur(30))
    shade = ImageChops.lighter(ImageChops.lighter(tight, pool), cast)
    dark = Image.new('RGB', (W, H), (14, 26, 60))
    scene = Image.composite(dark, scene, shade)

    scene.paste(cut, (x, y), cut)
    return scene


def main() -> None:
    for num, decor in SCENES.items():
        if not (DECORS / f'{decor}.png').exists():
            print('missing backdrop', decor)
            continue
        out = OUT / f'corps-{num}.jpg'
        compose(num, decor).save(out, quality=88, optimize=True, progressive=True)
        print(out.name, decor)


if __name__ == '__main__':
    main()
